sql.where:
t.deleted = 0

    AND t.rework_no = #{req.reworkNo}


    AND t.source_qc_task_id = #{req.sourceQcTaskId}


    AND t.qty = #{req.qty}


    AND t.route_id = #{req.routeId}


    AND t.route_version = #{req.routeVersion}


    AND t.status = #{req.status}


    AND t.remark = #{req.remark}


    AND t.create_time = #{req.createTime}
